// Manual run (demo button): same X-Ward-Secret as the event router.
const ok = $input.all().filter(i => (i.json.headers || {})['x-ward-secret'] === $env.N8N_EVENT_SECRET);
return ok.length ? [{ json: {} }] : [];

// GET /integrations/n8n/health-watch → WhatsApp advice for today and tomorrow (French + Arabic).
// Staff get the staff advice; patients get the patient advice when at least one patient is in a risk group.
// The messages carry no patient data.
const nums = (v) => [...new Set((v || '').split(',').map(s => s.replace(/\D/g, '')).filter(Boolean))];
const staff = nums($env.WARD_WHATSAPP_STAFF);
const patients = nums($env.WARD_WHATSAPP_PATIENT);
const res = $input.first().json;
if (res.statusCode !== 200) return [];
const body = res.body || {};
const today = DateTime.now().setZone('Africa/Tunis').toISODate();
const tomorrow = DateTime.now().setZone('Africa/Tunis').plus({ days: 1 }).toISODate();
const alerts = (body.alerts || []).filter(a => a.date === today || a.date === tomorrow);
if (!alerts.length) return [];
const when = (d) => d === today ? "aujourd'hui / اليوم" : 'demain / غدًا';
const demo = body.demo ? ' [démo]' : '';
const out = [];
const staffText = 'Ward · Veille santé' + demo + ' (' + body.city + ')\n' + alerts.map(a =>
  `• ${a.title.fr}, ${when(a.date)} — ${a.staff.fr}\n  ${a.title.ar}: ${a.staff.ar}` +
  (a.at_risk_count ? `\n  Patients à risque : ${a.at_risk_count}. Ouvrez Ward.` : '')).join('\n');
for (const to of staff) out.push({ json: { to, text: staffText } });
const forPatients = alerts.filter(a => a.at_risk_count > 0);
if (forPatients.length) {
  const text = 'Ward · Conseil santé' + demo + '\n' + forPatients.map(a =>
    `• ${a.title.fr}, ${when(a.date)} : ${a.patient.fr}\n  ${a.title.ar}: ${a.patient.ar}`).join('\n');
  for (const to of patients) out.push({ json: { to, text } });
}
return out;
